var Q18 = [
{n:1, q:'Los delitos relativos al ejercicio de los derechos fundamentales y libertades públicas están tipificados en:', o:{a:'El capítulo V, del Título XX, del Libro II del Código Penal.',b:'El capítulo IV, del Título XX, del Libro II del Código Penal.',c:'El capítulo V, del Título XXI, del Libro II del Código Penal.',d:'El capítulo IV, del Título XXI, del Libro II del Código Penal.'}, correct:'d', why:{d:'Los delitos relativos al ejercicio de los derechos fundamentales y libertades públicas están en el Capítulo IV, del Título XXI, del Libro II del CP.'}},
{n:2, q:'Los delitos relativos al ejercicio de los derechos fundamentales y libertades públicas del capítulo IV, del Título XXI, del Libro II del Código Penal...', o:{a:'Se estructuran en tres secciones.',b:'Comprenden los artículos 510 a 528.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Capítulo IV del Título XXI se estructura en tres secciones (a) y comprende los artículos 510 a 528 del CP (b).'}},
{n:3, q:'Dentro del capítulo IV, del Título XXI, del Libro II del Código Penal, la Sección Primera tiene por nombre...', o:{a:'De los delitos cometidos con ocasión del ejercicio de los derechos fundamentales y de las libertades públicas garantizados por la Constitución.',b:'De los delitos cometidos por los funcionarios públicos contra las garantías constitucionales.',c:'De los delitos contra las garantías establecidas en la Constitución para la protección de los derechos fundamentales y libertades públicas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Sección Primera del Cap.IV, Título XXI se denomina "De los delitos cometidos con ocasión del ejercicio de los derechos fundamentales y de las libertades públicas garantizados por la Constitución".'}},
{n:4, q:'Dentro del capítulo IV, del Título XXI, del Libro II del Código Penal, la Sección Segunda tiene por nombre...', o:{a:'De los delitos cometidos por los funcionarios públicos contra las garantías constitucionales.',b:'De los delitos contra la libertad de conciencia, los sentimientos religiosos y el respeto a los difuntos.',c:'De los delitos cometidos por los funcionarios públicos contra la libertad individual',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Sección Segunda del Cap.IV, Título XXI se denomina "De los delitos cometidos por los funcionarios públicos contra las garantías constitucionales".'}},
{n:5, q:'En la Sección Primera del Capítulo IV, del Título XXI, del Libro II del Código Penal, se contienen los artículos...', o:{a:'510 a 520.',b:'510 a 522.',c:'511 a 520.',d:'510 a 521'}, correct:'a', why:{a:'La Sección Primera del Cap.IV, Título XXI comprende los artículos 510 a 520 del CP.'}},
{n:6, q:'En la Sección Segunda del Capítulo IV, del Título XXI, del Libro II del Código Penal, se contienen los artículos...', o:{a:'520 a 529.',b:'520 a 528.',c:'522 a 528.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'La Sección Segunda del Cap.IV, Título XXI comprende los artículos 522 a 528 del CP.'}},
{n:7, q:'En la Sección Segunda del Capítulo IV, del Titulo XXI, del Libro II del Código Penal están sin contenido los artículos...', o:{a:'528 y 529.',b:'524 y 528.',c:'527 y 528.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Los artículos 527 y 528 del CP están sin contenido (derogados o vacíos) dentro de la Sección Segunda del Cap.IV, Título XXI.'}},
{n:8, q:'Los delitos de odio del artículo 510.1 del Código Penal se castigan con las penas de...', o:{a:'Prisión de 6 meses a 2 años y multa de 6 a 12 meses.',b:'Prisión de 1 a 4 años y multa de 6 a 12 meses.',c:'Prisión de 1 a 2 años y multa 4 a 12 meses.',d:'Prisión de 1 a 2 años y multa de 6 a 12 meses.'}, correct:'d', why:{d:'Art.510.1 CP: los delitos de odio se castigan con prisión de 1 a 4 años y multa de 6 a 12 meses.'}},
{n:9, q:'Quienes públicamente fomenten, promuevan o inciten al odio contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 a) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por motivos...', o:{a:'Racistas.',b:'Antisemitas.',c:'Antigitanos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.510.1.a CP: la incitación al odio por motivos racistas (a), antisemitas (b) o antigitanos (c) son todas circunstancias que dan lugar al delito de odio.'}},
{n:10, q:'Quienes públicamente fomenten, promuevan o inciten al odio contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 a) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por motivos...', o:{a:'Referentes a su ideología.',b:'Referentes a su sexo.',c:'Referentes a sus creencias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.510.1.a CP: también son motivos del delito de odio la ideología (a), el sexo (b) y las creencias (c).'}},
{n:11, q:'La incitación al odio contra un grupo, una parte del mismo o contra una persona determinada, del artículo 510.1 a) del Código Penal, se puede cometer...', o:{a:'Mediante acción, omisión, omisión por omisión, o de manera imprudente.',b:'Directa o indirectamente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.510.1.a CP: la incitación al odio puede cometerse directa o indirectamente (b). No se puede cometer por imprudencia (a es incorrecta).'}},
{n:12, q:'Quienes públicamente fomenten, promuevan o inciten al odio contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 a) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por motivos...', o:{a:'Referidos a su carácter.',b:'Referidos a su origen nacional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.510.1.a CP: el origen nacional (b) es motivo del delito de odio. El carácter (a) no está incluido expresamente en el art.510.'}},
{n:13, q:'Quienes públicamente fomenten, promuevan o inciten al odio contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 a) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por...', o:{a:'Razones de género.',b:'Su situación familiar.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.510.1.a CP: las razones de género (a) son motivo del delito de odio. La situación familiar (b) no está incluida expresamente.'}},
{n:14, q:'Quienes públicamente fomenten, promuevan o inciten al odio contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 a) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por razones de...', o:{a:'Enfermedad.',b:'Identidad sexual.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.510.1.a CP: la enfermedad (a) y la identidad sexual (b) son motivos del delito de odio.'}},
{n:15, q:'Quienes públicamente fomenten, promuevan o inciten al odio contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 a) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por razones de...', o:{a:'Aporofobia.',b:'Necrofobia.',c:'Androfobia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.510.1.a CP: la aporofobia (odio a los pobres) (a) está incluida en el art.510. La necrofobia y androfobia (b y c) no están expresamente recogidas.'}},
{n:16, q:'Quienes produzcan, elaboren o posean con la finalidad de distribuir, escritos o cualquier otra clase de material o soportes que por su contenido sean idóneos para fomentar, promover, o incitar al odio, hostilidad, discriminación o violencia contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 b) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por razones...', o:{a:'Referentes a su ideología.',b:'Referentes a su sexo.',c:'Referentes a sus creencias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.510.1.b CP: producir/distribuir material de odio por motivos de ideología (a), sexo (b) o creencias (c) constituye delito de odio.'}},
{n:17, q:'Quienes faciliten a terceras personas escritos o cualquier otra clase de material o soportes que por su contenido sean idóneos para fomentar, promover, o incitar al odio, hostilidad, discriminación o violencia contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 b) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por razones de...', o:{a:'Pertenencia a una nación.',b:'Pertenencia a un club deportivo.',c:'Pertenencia a una sociedad secreta.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.510.1.b CP: facilitar material de odio por razones de pertenencia a una nación (a) es delito. Los clubs deportivos y sociedades secretas (b y c) no están incluidos.'}},
{n:18, q:'Quienes distribuyan, difundan o vendan escritos o cualquier otra clase de material o soportes que por su contenido sean idóneos para fomentar, promover, o incitar al odio, hostilidad, discriminación o violencia contra un grupo, una parte del mismo o contra una persona determinada, pueden ser considerados autores de un delito de odio del artículo 510.1 b) del Código Penal, siempre y cuando esta conducta venga determinada por su pertenencia a dicho grupo, y por...', o:{a:'Razones relacionadas con religión o creencias.',b:'Razones relacionadas con el sexo, orientación o identidad sexual.',c:'Motivos referentes a la ideología, religión o creencias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.510.1.b CP: distribuir material de odio por razones de religión/creencias (a), sexo/orientación/identidad (b) o ideología (c) son conductas delictivas.'}},
{n:19, q:'Entre los elementos que configuran el delito de odio del artículo 510.1 c) del Código Penal está...', o:{a:'La trivialización grave del delito de lesa humanidad.',b:'El enaltecimiento del delito de genocidio.',c:'La negación de los delitos cometidos contra las personas y bienes protegidos en caso de conflicto armado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.510.1.c CP: la trivialización (a), el enaltecimiento del genocidio (b) y la negación de delitos en conflictos armados (c) son elementos del delito de odio del art.510.1.c.'}},
{n:20, q:'Entre los elementos que configuran el delito de odio del artículo 510.1 c) del Código Penal está...', o:{a:'El fomento de la hostilidad contra una persona o grupo determinado por motivos racistas.',b:'El enaltecimiento de los autores de los delitos cometidos contra las personas y bienes protegidos en caso de conflicto armado, siempre que de esta manera se promueva o favorezca un clima de violencia u hostilidad.',c:'La difusión de cualquier clase de material cuyo contenido sea idóneo para incitar a la discriminación por razones de género.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'Art.510.1.c CP: el enaltecimiento de autores de delitos en conflicto armado cuando promueve violencia u hostilidad (b) es elemento del delito de odio.'}},
{n:21, q:'Entre los elementos que configuran el delito de odio del artículo 510.1 c) del Código Penal está...', o:{a:'La incitación directa o indirecta contra una persona determinada por razón de su pertenencia a un determinado grupo, por motivos referentes a su religión.',b:'La posesión de cualquier soporte idóneo para incitar el odio contra un grupo o parte de él, por motivos de enfermedad o discapacidad.',c:'La negación de los delitos de genocidio, cuando se hubieren cometido contra un grupo o parte del mismo por motivos antisemitas, siempre que de esta manera se promueva o favorezca un clima de violencia u hostilidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Art.510.1.c CP: negar los delitos de genocidio cuando promueve violencia u hostilidad (c) es elemento específico del delito de odio.'}},
{n:22, q:'Los delitos de odio del artículo 510.2 del Código Penal se castigan con las penas de...', o:{a:'Prisión de 6 meses a 2 años y multa de 6 a 12 meses.',b:'Prisión de 1 a 4 años y multa de 6 a 12 meses.',c:'Prisión de 1 a 2 años y multa 4 a 12 meses.',d:'Prisión de 1 a 2 años y multa de 6 a 12 meses.'}, correct:'a', why:{a:'Art.510.2 CP: los delitos de odio del apartado 2 se castigan con prisión de 6 meses a 2 años y multa de 6 a 12 meses.'}},
{n:23, q:'Entre los elementos que configuran el delito de odio del artículo 510.2 a) del Código Penal está...', o:{a:'El enaltecimiento por cualquier medio de expresión pública de los delitos que hubieran sido cometidos contra un grupo por motivos antigitanos.',b:'Lesionar la dignidad de las personas mediante acciones que entrañen humillación por la pertenencia de éstas a alguno de los grupos a los que hace referencia el apartado 1 de este artículo.',c:'La difusión de cualquier clase de material cuyo contenido sea idóneo para incitar a la discriminación por razones de género.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.510.2.a CP: el enaltecimiento de delitos (a), lesionar la dignidad con humillación (b) y difundir material discriminatorio (c) son elementos del art.510.2.a.'}},
{n:24, q:'Entre los elementos que configuran el delito de odio del artículo 510.2 a) del Código Penal está...', o:{a:'Facilitar a terceras personas el acceso a cualquier clase de material que por su contenido sea idóneo para lesionar la dignidad de las personas por representar una grave humillación.',b:'La justificación por cualquier medio de expresión pública de los delitos que hubieran sido cometidos contra un grupo por razones de aporofobia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas'}, correct:'c', why:{c:'Art.510.2.a CP: facilitar acceso a material humillante (a) y justificar públicamente los delitos por aporofobia (b) son también elementos del tipo.'}},
{n:25, q:'Entre los elementos que configuran el delito de odio del artículo 510.2 a) del Código Penal está...', o:{a:'Difundir escritos que por su contenido sean idóneos para lesionar la dignidad de las personas por representar una grave humillación.',b:'Lesionar la dignidad de las personas mediante acciones que entrañen menosprecio o descrédito por la pertenencia de éstas a alguno de los grupos a los que hace referencia el apartado 1 de este artículo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas'}, correct:'c', why:{c:'Art.510.2.a CP: difundir escritos humillantes (a) y lesionar la dignidad con menosprecio (b) son conductas incluidas en el tipo.'}},
{n:26, q:'En el delito de odio del artículo 510.2 b) del Código Penal se castiga...', o:{a:'Justificar, por cualquier medio de expresión pública, los delitos que hubieran sido cometidos contra un grupo o parte del mismo por razón de su pertenencia a aquel, por motivos referentes a su ideología, religión o creencias.',b:'Enaltecer por cualquier medio de difusión los delitos cometidos contra un grupo o parte del mismo por razón de su pertenencia a aquel, por motivos referentes a su pertenencia a una etnia, raza o nación.',c:'Justificar, por cualquier medio de difusión, los delitos que hubieran sido cometidos contra un grupo o parte del mismo por razón de su pertenencia a aquel, por motivos referentes a su enfermedad o discapacidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.510.2.b CP: justificar o enaltecer delitos por cualquier medio (ideología, etnia, discapacidad, etc.) son conductas del tipo.'}},
{n:27, q:'En el delito de odio del artículo 510.2 b) del Código Penal se castiga...', o:{a:'Lesionar la dignidad de las personas mediante acciones que entrañen humillación por la pertenencia de éstas a alguno de los grupos a los que hace referencia el apartado 1 de este artículo.',b:'El enaltecimiento por cualquier medio de expresión pública de los delitos que hubieran sido cometidos contra un grupo por motivos referidos a su religión o creencias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.510.2.b CP: el enaltecimiento por medios de expresión pública de delitos por motivos religiosos (b) es conducta del tipo. La lesión de dignidad (a) corresponde al art.510.2.a.'}},
{n:28, q:'El delito de odio del artículo 510.2 b) del Código Penal será castigado con la pena de 1 a 4 años de prisión y multa de 6 a 12 meses, cuando...', o:{a:'Los hechos se hubieren llevado a cabo a través de un medio de comunicación social, por medio de internet o mediante el uso de tecnologías de la información, de modo que, aquel se hiciera accesible a un elevado número de personas.',b:'De este modo se promueva o favorezca un clima de violencia, hostilidad, odio o discriminación contra los mencionados grupos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.510.3 CP: la pena se eleva a 1-4 años cuando se usan medios de comunicación/internet accesibles masivamente (a) y cuando se promueve clima de violencia u odio (b).'}},
{n:29, q:'El delito de odio del artículo 510.2 b) del Código Penal será castigado con la pena de 1 a 4 años de prisión y multa de 6 a 12 meses,...', o:{a:'Cuando los hechos, a la vista de sus circunstancias, resulten idóneos para alterar la paz pública.',b:'Cuando se enaltezca o trivialice gravemente los delitos contra las personas y bienes protegidos en caso de conflicto armado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Las circunstancias de la opción a (alterar la paz pública) y b (trivializar delitos en conflictos) corresponden a otros supuestos del art.510, no son causas de agravación del art.510.2.b a 1-4 años.'}},
{n:30, q:'En los delitos de odio de los apartados 1 y 2 del artículo 510 del Código Penal, si los hechos se hubieren llevado a cabo a través de un medio de comunicación social, por medio de internet, o mediante el uso de tecnologías de la información, de modo que aquél se hiciera accesible a un elevado número de personas...', o:{a:'Se impondrá la pena superior en grado a la respectivamente prevista en cada caso.',b:'Se impondrá la pena prevista en su mitad superior.',c:'Se impondrá la pena en su mitad superior, que podrá elevarse hasta la superior en grado.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.510.3 CP: cuando se usan medios de comunicación masivos, la pena se impone en su mitad superior y puede elevarse hasta la superior en grado.'}},
{n:31, q:'En los delitos de odio de los apartados 1 y 2 del artículo 510 del Código Penal, cuando los hechos, a la vista de sus circunstancias, resulten idóneos para alterar la paz pública o crear un grave sentimiento de inseguridad o temor entre los integrantes del grupo...', o:{a:'Se impondrá la pena superior en grado a la respectivamente prevista en cada caso.',b:'Se impondrá la pena prevista en su mitad superior.',c:'Se impondrá la pena en su mitad superior, que podrá elevarse hasta la superior en grado.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.510.3 CP: cuando los hechos son idóneos para alterar la paz pública o crear inseguridad, la pena también se impone en mitad superior pudiendo elevarse hasta la superior en grado.'}},
{n:32, q:'En todos los casos de los delitos de odio de los apartados 1 y 2 del artículo 510 del Código Penal, además de las previstas en cada caso, se impondrá...', o:{a:'La pena de inhabilitación especial para profesión u oficio educativos, en el ámbito docente, por un tiempo de entre 3 y 10 años.',b:'La pena de inhabilitación especial para profesión u oficio educativos, en el ámbito deportivo, por un tiempo de entre 3 y 6 años.',c:'La pena de inhabilitación especial para profesión u oficio educativos, en el ámbito de tiempo libre, por un tiempo entre 4 y 8 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.510.4 CP: en todos los casos se impone inhabilitación especial para profesión u oficio educativos (docente, deportivo y tiempo libre) por tiempo entre 1 y 3 años; ninguna opción reproduce exactamente los términos del artículo.'}},
{n:33, q:'Dispone el artículo 510 bis del Código Penal que, cuando una persona jurídica sea responsable de los delitos de odio de los apartados 1 y 2 del artículo 510 del Código Penal, se le impondrá...', o:{a:'Pena de multa de 2 a 5 años.',b:'Cualquiera de las penas recogidas en el artículo 33.7 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.510 bis CP: cuando la persona jurídica es responsable, se le impone multa de 2 a 5 años (a) y cualquiera de las penas del art.33.7 CP (b).'}},
{n:34, q:'En el artículo 511.1 del Código Penal se castiga al particular encargado de un servicio público que deniegue a una persona una prestación a la que tenga derecho...', o:{a:'Por razón de su ideología.',b:'Por razón de su religión o creencias.',c:'Por razón de su situación familiar.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.511.1 CP: la denegación de prestación al particular por razón de ideología (a), religión (b) o situación familiar (c) son conductas del tipo.'}},
{n:35, q:'En el artículo 511.1 del Código Penal se castiga al funcionario o autoridad que deniegue a una persona una prestación a la que tenga derecho...', o:{a:'Por razón de su edad.',b:'Por razón de su identidad sexual.',c:'Por razón de la enfermedad que padezca o de su discapacidad.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'Art.511.1 CP: el funcionario que deniega prestaciones por edad, identidad sexual o discapacidad está en el tipo, y todas esas circunstancias son correctas; la d dice que todas son incorrectas, lo cual no es exacto. Sin embargo el libro marca d.'}},
{n:36, q:'El delito de odio del artículo 511.1 del Código Penal se castiga con las penas de...', o:{a:'Prisión de 1 a 2 años, multa de 12 a 24 meses e inhabilitación para empleo o cargo público por un tiempo de 1 a 3 años.',b:'Prisión de 6 meses a 2 años, multa de 12 a 24 meses e inhabilitación para empleo o cargo público por un tiempo de 1 a 3 años.',c:'Prisión de 1 a 3 años, multa de 6 a 12 meses e inhabilitación para empleo o cargo público por un tiempo de 2 a 5 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.511.1 CP: la denegación discriminatoria de prestaciones se castiga con prisión de 6 meses a 2 años, multa de 12 a 24 meses e inhabilitación para empleo o cargo público de 1 a 3 años.'}},
{n:37, q:'En el artículo 511.2 del Código Penal se castiga al particular encargado de un servicio público que deniegue a una asociación, fundación, sociedad, corporación, o contra sus miembros una prestación a la que tenga derecho...', o:{a:'Por razón de su origen nacional.',b:'Por razón de su religión o creencias.',c:'Por razón de aporofobia o exclusión social.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.511.2 CP: la denegación a asociaciones por razones de origen nacional (a), religión (b) u aporofobia (c) son conductas del tipo.'}},
{n:38, q:'Según el artículo 511.3 del Código Penal los funcionarios que cometan alguno de los hechos previstos en este artículo incurrirán en...', o:{a:'Las mismas penas que los particulares encargados de algún servicio público, que cometiesen estos hechos.',b:'Las mismas penas que los particulares encargados de algún servicio público, que cometiesen estos hechos, en su mitad superior.',c:'Las mismas penas que los particulares encargados de algún servicio público, que cometiesen estos hechos, en su mitad superior, y en la de inhabilitación especial para empleo o cargo público por tiempo de dos a cuatro años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.511.3 CP: los funcionarios que cometan los hechos del art.511 incurren en las mismas penas que los particulares, en su mitad superior, más inhabilitación especial de 2 a 4 años.'}},
{n:39, q:'Según el artículo 511.4 del Código Penal, en todos los casos previstos en este artículo se impondrá, además de las penas respectivamente previstas, la de ...', o:{a:'Inhabilitación especial para profesión u oficio educativos, en el ámbito docente, deportivo y de tiempo libre, por un tiempo superior entre 1 y 3 años al de la duración de la pena impuesta, si esta fuere de privación de libertad.',b:'Inhabilitación especial para profesión u oficio educativos, en el ámbito docente, deportivo y de tiempo libre, por un tiempo de 1 a 3 años, si la pena impuesta fuere de multa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.511.4 CP: la inhabilitación especial para actividades educativas se impone en función de si la pena es privativa de libertad (a) o multa (b).'}},
{n:40, q:'En el artículo 512 del Código Penal, se castiga la denegación de prestaciones a las que tiene derecho una persona ...', o:{a:'Por parte de una autoridad o funcionario público.',b:'Por razón de su ideología, religión o creencias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.512 CP: la conducta punible no es por autoridad (a) ni por esas razones específicas (b), sino que el art.512 castiga a quienes en el ejercicio de actividades profesionales o empresariales denieguen prestaciones. Las opciones a y b no describen exactamente el tipo.'}},
{n:41, q:'En el artículo 512 del Código Penal, se castiga la denegación de prestaciones a las que tiene derecho una persona ...', o:{a:'Por quienes realicen el ejercicio de sus actividades profesionales o empresariales.',b:'Por razón de su pertenencia a una etnia, raza o nación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.512 CP: los sujetos activos son quienes ejercen actividades profesionales o empresariales (a) y la denegación puede ser por etnia, raza o nación (b).'}},
{n:42, q:'Los delitos de odio del artículo 512 del Código Penal, se castigan con la pena de...', o:{a:'Inhabilitación especial para el ejercicio de profesión, oficio, industria o comercio, por un periodo de 1 a 4 años.',b:'Inhabilitación especial para empleo o cargo público por un periodo de 1 a 4 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.512 CP: la denegación discriminatoria por profesionales se castiga con inhabilitación especial para el ejercicio de profesión, oficio, industria o comercio de 1 a 4 años.'}},
{n:43, q:'Los delitos de odio del artículo 512 del Código Penal, se castigan con la pena de...', o:{a:'Inhabilitación especial para profesión u oficio educativos, en el ámbito docente, deportivo y de tiempo libre, por un tiempo de 1 a 2 años.',b:'Inhabilitación especial para profesión u oficio educativos, en el ámbito docente, deportivo y de tiempo libre, por un tiempo de 1 a 3 años.',c:'Inhabilitación especial para profesión u oficio educativos, en el ámbito docente, deportivo y de tiempo libre, por un tiempo de 1 a 4 años.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'Art.512 CP: además de la inhabilitación profesional, se impone inhabilitación especial para actividades educativas de 1 a 4 años.'}},
{n:44, q:'Según el artículo 513 del Código Penal son punibles las reuniones o manifestaciones ilícitas, y tienen tal consideración...', o:{a:'Las que se celebren con el fin de cometer cualquier delito.',b:'Las que no hayan sido comunicadas en tiempo y forma de acuerdo con la Ley Orgánica que las desarrolle.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.513 CP: son ilícitas las que se celebran para cometer delito (a) y las no comunicadas en tiempo y forma (b).'}},
{n:45, q:'Según el artículo 513 del Código Penal son punibles las reuniones o manifestaciones ilícitas, y tienen tal consideración...', o:{a:'Aquellas a las que concurran personas con armas.',b:'Aquellas a las que concurran personas con objetos contundentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.513 CP: también son ilícitas las reuniones a las que concurran personas con armas (a) u objetos contundentes (b).'}},
{n:46, q:'Según el artículo 513 del Código Penal son punibles las reuniones o manifestaciones ilícitas, y tienen tal consideración...', o:{a:'Aquellas a las que concurran personas con ropas o símbolos que inciten al racismo o la xenofobia.',b:'Aquellas a las que concurran personas con artefactos explosivos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.513 CP: reuniones con personas portando ropas racistas/xenófobas (a) o artefactos explosivos (b) también son ilícitas.'}},
{n:47, q:'Con respecto al delito del artículo 514.1 del Código Penal, indique la respuesta correcta...', o:{a:'Se castiga a los promotores o directores de cualquier reunión o manifestación ilícita.',b:'Se reputan directores o promotores a los que las convoquen o presidan.',c:'La conducta punible consiste en no haber tratado de impedir por todos los medios a su alcance lo que se dice en el artículo 513 CP.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.514.1 CP: se castiga a promotores y directores (a), que son quienes las convocan o presiden (b), y la conducta es no haber intentado impedir lo ilícito (c).'}},
{n:48, q:'Con respecto al delito del artículo 514.2 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de este delito solo pueden ser los promotores o directores de la manifestación ilícita.',b:'Se castiga con las penas de prisión de 1 a 2 años y multa de 6 a 12 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.514.2 CP: cualquier persona que provoque o favorezca el desorden en reuniones o manifestaciones se castiga con prisión de 1 a 2 años y multa de 6 a 12 meses.'}},
{n:49, q:'Con respecto al delito del artículo 514.3 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de este delito puede ser cualquier persona.',b:'La conducta punible consiste en realizar actos de violencia contra la autoridad, sus agentes, personas o propiedades, con ocasión de una reunión o manifestación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.514.3 CP: el sujeto activo puede ser cualquier persona (a) y la conducta es realizar actos de violencia con ocasión de reunión o manifestación (b).'}},
{n:50, q:'El delito del artículo 514.3 del Código Penal consistente en ejercer actos de violencia contra la autoridad, sus agentes, personas o propiedades, con ocasión de una reunión o manifestación, se castiga...', o:{a:'Con las penas de prisión de 1 a 2 años y multa de 6 a 12 meses.',b:'Con la pena que a su delito corresponda.',c:'Con la pena que a su delito corresponda, en su mitad superior.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.514.3 CP: los actos de violencia en reuniones se castigan con la pena que corresponda al delito cometido, en su mitad superior.'}},
{n:51, q:'Con respecto al delito del artículo 514.4 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de este delito solo puede ser una autoridad o funcionario público.',b:'La conducta punible consiste en impedir el legítimo ejercicio de las libertades de reunión o manifestación lícita.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.514.4 CP: la conducta punible es impedir el legítimo ejercicio de las libertades de reunión o manifestación lícita (b). El sujeto activo puede ser cualquier persona.'}},
{n:52, q:'Con respecto al delito del artículo 514.4 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de este delito puede ser cualquier persona.',b:'La conducta punible consiste en perturbar gravemente el desarrollo de una reunión o manifestación lícita.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.514.4 CP: el sujeto activo puede ser cualquier persona (a) y también la conducta de perturbar gravemente una reunión lícita (b) es punible.'}},
{n:53, q:'El delito del artículo 514.4 del Código Penal consistente impedir el legítimo ejercicio de las libertades de reunión y manifestación, o perturbar gravemente el desarrollo de una manifestación lícita, se castiga...', o:{a:'Con las penas de prisión de 1 a 2 años y multa de 6 a 12 meses, si los hechos se realizan con violencia.',b:'Con la pena de prisión de 3 a 6 meses, o multa de 6 a 12 meses, si los hechos se cometieren mediante vías de hecho o cualquier otro procedimiento ilegítimo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.514.4 CP: con violencia la pena es 1-2 años y multa 6-12 meses (a); mediante vías de hecho u otros procedimientos ilegítimos la pena es 3-6 meses o multa 6-12 meses (b).'}},
{n:54, q:'Con respecto al delito del artículo 514.5 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de este delito puede ser cualquier persona.',b:'La conducta punible consiste en convocar, celebrar o intentar celebrar de nuevo una reunión o manifestación previamente suspendida o prohibida, siempre que con ello pretendan subvertir el orden constitucional o alterar gravemente la paz pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.514.5 CP: el sujeto activo puede ser cualquier persona (a) y la conducta es convocar/celebrar reunión suspendida con fin subversivo (b).'}},
{n:55, q:'El delito del artículo 514.5 del Código Penal, consistente en convocar, celebrar o intentar celebrar de nuevo una reunión o manifestación previamente suspendida o prohibida, siempre que con ello pretendan subvertir el orden constitucional o alterar gravemente la paz pública, se castiga...', o:{a:'Con las penas de prisión de 6 meses a 1 año y multa de 6 a 12 meses, si los hechos se realizan con violencia.',b:'Con las penas de prisión de 6 meses a 1 año y multa de 6 a 12 meses, sin perjuicio de la pena que pudiera corresponder, en su caso, conforme a los apartados precedentes de este artículo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.514.5 CP: se castiga con prisión de 6 meses a 1 año y multa de 6 a 12 meses, sin perjuicio de otras penas que pudieran corresponder.'}},
{n:56, q:'Según el artículo 515 del Código Penal, son punibles las asociaciones ilícitas, y tienen tal consideración...', o:{a:'Las que tengan por objeto cometer algún delito o, después de constituidas promuevan su comisión.',b:'Las organizaciones esotéricas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.515 CP: son ilícitas las que tienen por objeto cometer algún delito o las promueven tras constituirse (a). Las organizaciones esotéricas (b) no están expresamente incluidas.'}},
{n:57, q:'Según el artículo 515 del Código Penal, son punibles las asociaciones ilícitas, y tienen tal consideración...', o:{a:'Las que, teniendo un fin lícito, empleen medios violentos o de alteración o control de la personalidad para su consecución.',b:'Las organizaciones paramilitares.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.515 CP: son también ilícitas las que usan medios violentos para fin lícito (a) y las organizaciones paramilitares (b).'}},
{n:58, q:'Según el artículo 515.4 del Código Penal, son punibles las asociaciones ilícitas, y tienen tal consideración...', o:{a:'Las que fomenten el odio contra personas, grupos o asociaciones, por razón de su ideología.',b:'Las que promuevan la discriminación de personas, grupos o asociaciones, por razón de su orientación o identidad sexual o de género.',c:'Las que inciten, directa o indirectamente, a la violencia contra las personas, grupos o asociaciones, por razón de una situación de aporofobia o exclusión social.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.515.4 CP: fomentar odio por ideología (a), promover discriminación por orientación/identidad sexual (b) e incitar a la violencia por aporofobia (c) son formas de asociación ilícita.'}},
{n:59, q:'Según el artículo 517 del Código Penal, a los fundadores, directores y presidentes de las asociaciones ilícitas, se les impondrán las penas de...', o:{a:'Prisión de 2 a 4 años, multa de 12 a 24 meses, e inhabilitación especial para empleo o cargo público por tiempo de 6 a 12 años.',b:'Prisión de 2 a 4 años, multa de 6 a 12 meses, e inhabilitación especial para empleo o cargo público por tiempo de 6 a 12 años.',c:'Prisión de 1 a 3 años y multa de 12 a 24 meses.',d:'Prisión de 1 a 3 años o multa de 12 a 24 meses.'}, correct:'a', why:{a:'Art.517 CP: los fundadores, directores y presidentes de asociaciones ilícitas se castigan con prisión de 2 a 4 años, multa de 12 a 24 meses e inhabilitación especial de 6 a 12 años.'}},
{n:60, q:'Según el artículo 517 del Código Penal, a los miembros activos de las asociaciones ilícitas, se les impondrán las penas de...', o:{a:'Prisión de 2 a 4 años, multa de 12 a 24 meses, e inhabilitación especial para empleo o cargo público por tiempo de 6 a 12 años.',b:'Prisión de 2 a 4 años, multa de 6 a 12 meses, e inhabilitación especial para empleo o cargo público por tiempo de 6 a 12 años.',c:'Prisión de 1 a 3 años y multa de 12 a 24 meses.',d:'Prisión de 1 a 3 años o multa de 12 a 24 meses.'}, correct:'c', why:{c:'Art.517 CP: los miembros activos de asociaciones ilícitas se castigan con prisión de 1 a 3 años y multa de 12 a 24 meses.'}},
{n:61, q:'Con respecto al delito del artículo 518 del Código Penal, indique la respuesta que no es correcta...', o:{a:'Sujeto activo de este delito puede ser cualquier persona.',b:'La conducta punible consiste en favorecer la fundación, organización o actividad de asociaciones ilícitas comprendidas en los apartados 1º, y 3º al 6º del artículo 515 del Código Penal.',c:'El favorecimiento debe realizarse exclusivamente mediante cooperación económica.',d:'Este delito se castiga con las penas de prisión de 1 a 3 años, multa de 12 a 24 meses, e inhabilitación para empleo o cargo público de 1 a 4 años.'}, correct:'c', why:{c:'La opción c es incorrecta: el art.518 CP no limita el favorecimiento a la cooperación económica; puede realizarse por cualquier medio.'}},
{n:62, q:'En el artículo 519 del Código Penal se castiga la provocación, conspiración y proposición para cometer el delito de asociación ilícita. Respecto a su pena a imponer, indique la respuesta correcta.', o:{a:'Se impone la pena prevista en cada caso, en su mitad inferior.',b:'Se impone la pena inferior en grado a la que corresponda en cada caso',c:'Se impone la pena inferior en uno o dos grados a la que corresponda en cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.519 CP: la provocación, conspiración y proposición para asociación ilícita se castigan con la pena inferior en grado a la que corresponda.'}},
{n:63, q:'Según el artículo 520 del Código Penal, en los supuestos previstos en el artículo 515 de este Código, los Jueces o Tribunales acordarán...', o:{a:'La disolución de la asociación ilícita.',b:'Cualquier otra consecuencia accesoria de las establecidas en el artículo 127 de este Código.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.520 CP: los jueces acordarán la disolución de la asociación ilícita (a) y cualquier consecuencia accesoria del art.127 CP (b).'}},
{n:64, q:'Según el artículo 521 del Código Penal, en los delitos de asociación ilícita, si el reo fuera autoridad, agente de ésta o funcionario público...', o:{a:'Además de las penas señaladas en cada caso se le impondrá la de inhabilitación especial para empleo o cargo público de 10 a 15 años.',b:'Además de las penas señaladas en cada caso se le impondrá la de inhabilitación absoluta de 10 a 15 años.',c:'Además de las penas señaladas en cada caso se le impondrá la de inhabilitación especial para profesión u oficio educativos, en el ámbito docente, deportivo y de tiempo libre, por un tiempo de 10 a 15 años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.521 CP: cuando el reo es autoridad, funcionario o agente se impone inhabilitación especial para empleo/cargo (a), inhabilitación absoluta (b) e inhabilitación para actividades educativas (c).'}},
{n:65, q:'Con respecto a los delitos contra la libertad de conciencia y los sentimientos religiosos del artículo 522.1 del Código Penal, indique la respuesta correcta...', o:{a:'Se castiga a los que fuercen a otro u otros a practicar o concurrir a actos de culto o ritos.',b:'Se castiga a los que fuercen a otro u otros a realizar actos reveladores de profesar o no profesar una religión, o mudar la que profesen.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.522.1 CP: se castiga forzar a practicar cultos (a) y forzar a manifestar creencias o cambiar de religión (b).'}},
{n:66, q:'Con respecto a los delitos contra la libertad de conciencia y los sentimientos religiosos del artículo 522.2 del Código Penal, indique la respuesta correcta...', o:{a:'Se castiga a los que por medio de violencia impidan a un miembro o miembros de una confesión religiosa practicar los actos propios de las creencias que profesen.',b:'Se castiga a los que por medio de cualquier apremio ilegítimo, impidan a un miembro o miembros de una confesión religiosa asistir a los actos propios de las creencias que profesen.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.522.2 CP: se castiga impedir mediante violencia (a) o apremio ilegítimo (b) practicar o asistir a actos religiosos.'}},
{n:67, q:'En el artículo 522 del Código Penal...', o:{a:'Se castiga a los que por medio de violencia o intimidación, fuerza o cualquier otro apremio ilegítimo impidan a un miembro o miembros de una confesión religiosa practicar los actos propios de las creencias que profesan, o asistir a los mismos.',b:'Se castiga a los que por medio de violencia o intimidación, fuerza o cualquier otro apremio ilegítimo fuercen a otro u otros a profesar o no profesar una religión o a mudar la que profesen.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.522 CP: se castigan tanto impedir la práctica religiosa (a) como forzar a profesar o cambiar de religión (b).'}},
{n:68, q:'En los delitos contra la libertad de conciencia y los sentimientos religiosos del artículo 522 del Código Penal...', o:{a:'Se castiga a los que por medio de violencia o intimidación, fuerza o cualquier otro apremio ilegítimo impidan a un miembro o miembros de una confesión religiosa practicar los actos propios de las creencias que profesan, o asistir a los mismos.',b:'Se castiga a los que por medio de violencia o intimidación, fuerza o cualquier otro apremio ilegítimo fuercen a otro u otros a profesar o no profesar una religión o a mudar la que profesen.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.522 CP: ambas conductas (impedir la práctica religiosa e imponer creencias) están tipificadas.'}},
{n:69, q:'Con respecto a los delitos contra los sentimientos religiosos del artículo 523 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de estos delitos puede ser cualquier persona.',b:'La conducta punible consiste en interrumpir o perturbar los actos, funciones, ceremonias o manifestaciones de las confesiones religiosas que se hallen inscritas en el registro público del Ministerio de Justicia e Interior.',c:'Para que exista delito debe emplearse violencia, amenaza, tumulto o vías de hecho.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.523 CP: sujeto activo puede ser cualquier persona (a), la conducta es interrumpir actos religiosos inscritos (b) y se requiere violencia, amenaza, tumulto o vías de hecho (c).'}},
{n:70, q:'Los delitos contra los sentimientos religiosos del artículo 523 del Código Penal se castigan...', o:{a:'Con la pena de prisión de 6 meses a 6 años, si el hecho se hubiere cometido en lugar destinado al culto.',b:'Con la pena multa de 1 a 4 meses, si el hecho se realizare en cualquier otro lugar que no esté destinado al culto.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.523 CP: prisión de 6 meses a 6 años en lugar de culto (a) y multa de 1 a 4 meses en cualquier otro lugar (b).'}},
{n:71, q:'En lo que respecta al delito contra los sentimientos religiosos del artículo 524 del Código Penal, indique la respuesta incorrecta...', o:{a:'Sujeto activo de este delito puede ser cualquier persona.',b:'La conducta punible consiste en ejecutar actos de profanación en ofensa de los sentimientos religiosos legalmente tutelados.',c:'Para que exista delito debe emplearse violencia, amenaza, tumulto o vías de hecho.',d:'Para que exista delito los hechos los actos deben realizarse en templo o lugar destinado al culto, o en ceremonias religiosas.'}, correct:'c', why:{c:'La opción c es incorrecta: el art.524 CP no requiere violencia, amenaza o tumulto; basta con ejecutar actos de profanación en ofensa de los sentimientos religiosos.'}},
{n:72, q:'Los delitos contra los sentimientos religiosos del artículo 524 del Código Penal se castigan...', o:{a:'Con la pena de prisión de 1 a 2 años o multa de 12 a 24 meses.',b:'Con la pena de prisión de 6 meses a un año o multa de 12 a 24 meses.',c:'Con la pena de prisión de 6 meses a 6 años, si el hecho se hubiere cometido en lugar destinado al culto.',d:'Con la pena multa de 1 a 4 meses, si el hecho se realizare en cualquier otro lugar que no esté destinado al culto.'}, correct:'a', why:{a:'Art.524 CP: los actos de profanación se castigan con prisión de 1 a 2 años o multa de 12 a 24 meses.'}},
{n:73, q:'En lo que respecta al delito contra los sentimientos religiosos del artículo 525 del Código Penal, indique la respuesta incorrecta...', o:{a:'Sujeto activo de este delito puede ser cualquier persona.',b:'La conducta punible consiste en hacer de manera pública y violenta, a través de palabra, escrito o mediante cualquier tipo de documento, escarnio de los dogmas, creencias, ritos o ceremonias de una confesión religiosa.',c:'La conducta punible consiste en vejar, de manera pública, a quienes profesen o practiquen ritos o ceremonias de una confesión religiosa.',d:'Para que exista delito las conductas tipificadas deben realizarse con la finalidad de ofender los sentimientos de los miembros de una confesión religiosa.'}, correct:'d', why:{d:'La opción d es incorrecta: el art.525 CP no requiere que la finalidad sea específicamente ofender los sentimientos religiosos; basta con el escarnio público de dogmas o ritos.'}},
{n:74, q:'En los delitos contra los sentimientos religiosos del artículo 525 del Código Penal...', o:{a:'Se castiga con la pena de multa de 8 a 12 meses a quienes, para ofender los sentimientos de los miembros de una confesión religiosa, hagan públicamente, de palabra, por escrito o mediante cualquier tipo de documento, escarnio de sus dogmas, creencias, ritos o ceremonias.',b:'Se castiga con multa de 8 a 12 meses a quienes hagan públicamente escarnio, de palabra o por escrito, de quienes no profesan religión o creencia alguna.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.525 CP: tanto el escarnio de confesiones religiosas (a) como el escarnio de quienes no profesan ninguna religión (b) se castigan con multa de 8 a 12 meses.'}},
{n:75, q:'En el artículo 526 del Código Penal se castiga al que, faltando al respeto debido a la memoria de los muertos...', o:{a:'Violare los sepulcros o sepulturas.',b:'Ejecute actos de profanación en ofensa de los sentimientos religiosos legalmente tutelados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.526 CP: el delito de falta de respeto a los muertos incluye violar sepulcros o sepulturas (a). Los actos de profanación religiosa (b) corresponden al art.524.'}},
{n:76, q:'En el artículo 526 del Código Penal, se castiga al que, faltando al respeto debido a la memoria de los muertos...', o:{a:'Profanare un cadáver o sus cenizas.',b:'Con ánimo de ultraje, destruyere, dañare o alterare las urnas funerarias.',c:'Con ánimo de ultraje, destruyere, dañare o alterare panteones, lápidas o nichos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.526 CP: profanar cadáveres (a), destruir urnas funerarias (b) y dañar panteones/lápidas/nichos (c) son conductas del tipo.'}},
{n:77, q:'El delito de falta de respeto a la memoria de los muertos, del artículo 526 del Código Penal se castiga...', o:{a:'Con la pena de prisión de 3 a 6 meses a un año o multa de 12 a 24 meses.',b:'Con la pena de prisión 3 a 5 meses o multa de 6 a 10 meses.',c:'Con la pena multa de 1 a 4 meses.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.526 CP: el delito de falta de respeto a la memoria de los muertos se castiga con multa de 1 a 4 meses.'}},
{n:78, q:'Los delitos cometidos por funcionarios públicos contra las garantías constitucionales están tipificados en:', o:{a:'El capítulo V, del Título XX, del Libro II del Código Penal.',b:'El capítulo IV, del Título XX, del Libro II del Código Penal.',c:'El capítulo V, del Título XXI, del Libro II del Código Penal.',d:'El capítulo IV, del Título XXI, del Libro II del Código Penal.'}, correct:'d', why:{d:'Los delitos de funcionarios contra las garantías constitucionales están en la Sección Segunda del Cap.IV, Título XXI, Libro II del CP.'}},
{n:79, q:'Los delitos cometidos por los funcionarios públicos contra las garantías constitucionales del capítulo V, del Título XXI, del Libro II del Código Penal...', o:{a:'Se estructuran en tres secciones.',b:'Comprenden los artículos 510 a 528.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Sección Segunda del Cap.IV Título XXI (delitos de funcionarios contra garantías constitucionales) también se estructura en tres secciones.'}},
{n:80, q:'Dentro del capítulo V, del Título XXI, del Libro II del Código Penal, la Sección Primera tiene por nombre...', o:{a:'De los delitos cometidos por los funcionarios públicos contra la libertad individual.',b:'De los delitos cometidos por los funcionarios públicos contra otros derechos individuales.',c:'De los delitos cometidos por los funcionarios públicos contra la inviolabilidad domiciliaria y demás garantías de la intimidad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Sección Primera del Cap.V del Título XXI se denomina "De los delitos cometidos por los funcionarios públicos contra la libertad individual".'}},
{n:81, q:'Dentro del capítulo V, del Título XXI, del Libro II del Código Penal, la Sección Segunda tiene por nombre...', o:{a:'De los delitos cometidos por los funcionarios públicos contra la libertad individual.',b:'De los delitos cometidos por los funcionarios públicos contra otros derechos individuales.',c:'De los delitos cometidos por los funcionarios públicos contra las garantías constitucionales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Sección Segunda del Cap.V del Título XXI se denomina "De los delitos cometidos por los funcionarios públicos contra las garantías constitucionales".'}},
{n:82, q:'Dentro del capítulo V, del Título XXI, del Libro II del Código Penal, la Sección Tercera tiene por nombre...', o:{a:'De los delitos cometidos por los funcionarios públicos contra la libertad individual.',b:'De los delitos cometidos por los funcionarios públicos contra otros derechos individuales.',c:'De los delitos cometidos por los funcionarios públicos contra la inviolabilidad domiciliaria y demás garantías de la intimidad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'La Sección Tercera del Cap.V del Título XXI se denomina "De los delitos cometidos por los funcionarios públicos contra otros derechos individuales".'}},
{n:83, q:'En la Sección Primera del Capítulo V, del Título XXI, del Libro II del Código Penal, se contienen los artículos...', o:{a:'534 a 536.',b:'537 a 542.',c:'529 a 533.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'La Sección Primera del Cap.V, Título XXI comprende los artículos 529 a 533 del CP.'}},
{n:84, q:'En la Sección Segunda del Capítulo V, del Título XXI, del Libro II del Código Penal, se contienen los artículos...', o:{a:'534 a 536.',b:'537 a 542.',c:'529 a 533.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Sección Segunda del Cap.V, Título XXI comprende los artículos 534 a 536 del CP.'}},
{n:85, q:'En la Sección Tercera del Capítulo V, del Título XXI, del Libro II del Código Penal, se contienen los artículos...', o:{a:'534 a 536.',b:'537 a 542.',c:'529 a 533.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'La Sección Tercera del Cap.V, Título XXI comprende los artículos 537 a 542 del CP.'}},
{n:86, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público del artículo 529 del Código Penal, indique la respuesta incorrecta:', o:{a:'Sujeto activo de este delito puede ser cualquier funcionario público.',b:'La conducta punible consiste en causar una causa criminal a otra autoridad o funcionario que ilegalmente se la reclame.',c:'Este delito se castiga con la pena de inhabilitación especial para empleo o cargo público de 6 meses a 2 años.',d:'Si, además, se entregara la persona de un detenido, se le impondrá la pena superior en grado.'}, correct:'b', why:{b:'La opción b es incorrecta: el art.529 CP castiga al funcionario que DEJA DE practicar la detención de una persona que deba ser detenida, o que ENTREGA a un detenido a quien lo reclama ilegalmente.'}},
{n:87, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público del artículo 530 del Código Penal, indique la respuesta incorrecta:', o:{a:'La conducta punible consiste en acordar, practicar o prolongar cualquier privación de libertad de un detenido, preso o sentenciado.',b:'Para que se pueda aplicar este tipo penal es necesario que medie causa por delito.',c:'Para que exista delito es necesario que se produzca una violación de los plazos o demás garantías constitucionales o legales.',d:'Este delito se castiga con la pena de inhabilitación especial para empleo o cargo público de 6 meses a 2 años.'}, correct:'b', why:{b:'La opción b es incorrecta: el art.530 CP no requiere que medie causa por delito; el delito se produce por prolongar la privación de libertad más allá de los plazos legales.'}},
{n:88, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público del artículo 531 del Código Penal, indique la respuesta incorrecta:', o:{a:'La conducta punible consiste en acordar, practicar o prolongar cualquier privación de libertad de un detenido, preso o sentenciado.',b:'Para que se pueda aplicar este tipo penal es necesario que medie causa por delito.',c:'Para que exista delito es necesario que se produzca una violación de los plazos o demás garantías constitucionales o legales.',d:'Este delito se castiga con la pena de inhabilitación especial para empleo o cargo público de 2 a 6 años.'}, correct:'b', why:{b:'La opción b es incorrecta por la misma razón: el art.531 CP tampoco requiere causa por delito como elemento del tipo.'}},
{n:89, q:'En el artículo 532 del Código Penal, ...', o:{a:'Se castigan los hechos descritos en los artículos 529 a 531 de este Código, cuando fueren cometidos por imprudencia grave.',b:'Se impone la pena de inhabilitación especial para empleo o cargo público de 2 a 6 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.532 CP: los delitos de los arts.529-531 cometidos por imprudencia grave (a) se castigan con inhabilitación especial de 2 a 6 años (b).'}},
{n:90, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público del artículo 533 del Código Penal, indique la respuesta incorrecta...', o:{a:'Sujeto activo de este delito puede ser cualquier funcionario público.',b:'La conducta punible consiste en imponer a los reclusos o internos sanciones o privaciones indebidas.',c:'La conducta punible consiste en usar un rigor innecesario con los reclusos o internos.',d:'Este delito se castiga con la pena de inhabilitación especial para empleo o cargo público de 2 a 6 años.'}, correct:'d', why:{d:'La opción d es incorrecta: la pena del art.533 CP es inhabilitación especial para empleo o cargo público de 2 a 4 años, no de 2 a 6 años.'}},
{n:91, q:'En lo que respecta a los delitos contra la libertad individual cometidos por funcionario público, del artículo 534.1 del Código Penal, indique la respuesta incorrecta...', o:{a:'Sujeto activo de estos delitos solo puede ser una autoridad o funcionario público.',b:'La conducta punible consiste en interceptar cualquier clase de correspondencia privada, postal o telegráfica, con violación de las garantías constitucionales o legales.',c:'La conducta punible consiste en entrar en un domicilio sin el consentimiento del morador.',d:'Para que se produzca este delito debe mediar causa por delito y que no se respeten las garantías constitucionales o legales.'}, correct:'c', why:{c:'La opción c es incorrecta: el art.534.1 CP tipifica la interceptación de correspondencia privada, no la entrada en domicilio (que es un delito distinto del art.534.2 o 204 CP).'}},
{n:92, q:'En lo que respecta a los delitos contra la libertad individual cometidos por funcionario público, del artículo 534.1 del Código Penal, indique la respuesta incorrecta...', o:{a:'Estos delitos se castigan con las penas de multa de 6 a 18 meses e inhabilitación especial para empleo o cargo público de 2 a 6 años.',b:'La conducta punible consiste en registrar los papeles o documentos de una persona o los efectos que se hallen en su domicilio, sin que el dueño de los mismos haya prestado libremente su consentimiento.',c:'Debe mediar causa por delito y que no se respeten las garantías constitucionales o legales.',d:'Si no se devolvieran al dueño dichos papeles o documentos, inmediatamente después del registro, se impondrán las penas de inhabilitación especial para empleo o cargo público de 6 a 12 años y multa de 12 a 24 meses, sin perjuicio de la pena que pudiere corresponder por la apropiación.'}, correct:'b', why:{b:'La opción b describe la conducta del art.534.2 (registro de papeles en domicilio), no del art.534.1 (interceptación de correspondencia).'}},
{n:93, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público, del artículo 534.2 del Código Penal, indique la respuesta correcta...', o:{a:'La conducta punible consiste en interceptar cualquier clase de correspondencia privada, postal o telegráfica, con violación de las garantías constitucionales o legales.',b:'La conducta punible consiste en registrar los papeles o documentos de una persona o los efectos que se hallen en su domicilio, sin que el dueño de los mismos haya prestado libremente su consentimiento.',c:'La conducta punible consiste en cometer cualquier vejación injusta o daño innecesario, con ocasión de un ilícito registro de papeles, documentos o efectos de una persona.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.534.2 CP: la conducta consiste en registrar los papeles/documentos en el domicilio sin consentimiento del dueño (b).'}},
{n:94, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público, del artículo 534.5 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de este delito puede ser cualquier autoridad o funcionario público.',b:'La conducta punible consiste en interceptar cualquier clase de correspondencia privada, postal o telegráfica, con violación de las garantías constitucionales o legales.',c:'Por la comisión de este delito se impone la pena de inhabilitación especial para empleo o cargo público de 2 a 6 años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.534.5 CP: autoridad o funcionario público (a), interceptar correspondencia (b) e inhabilitación especial de 2 a 6 años (c) son todos elementos correctos.'}},
{n:95, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público, del artículo 535 del Código Penal, si se divulgara o revelara la información obtenida, se impondrá la pena de...', o:{a:'Inhabilitación especial para empleo o cargo público de 2 a 6 años, en su mitad superior.',b:'Multa de 6 a 18 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.535 CP: si se divulga o revela la información obtenida ilegalmente, se impone inhabilitación especial para empleo o cargo público de 2 a 6 años en su mitad superior.'}},
{n:96, q:'En lo que respecta a los delitos contra la libertad individual cometidos por funcionario público, del artículo 536 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de estos delitos solo pueden serlo las autoridades, funcionarios públicos, o agentes de éstos.',b:'La conducta punible consiste en interceptar las telecomunicaciones, con violación de las garantías constitucionales o legales.',c:'La conducta punible consiste en utilizar artificios técnicos de escucha, transmisión, grabación o reproducción del sonido, de la imagen o de cualquier otra señal de comunicación, con violación de las garantías constitucionales o legales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.536 CP: el sujeto activo son autoridades/funcionarios o agentes (a), las conductas son interceptar telecomunicaciones (b) y usar artificios técnicos de escucha/grabación (c).'}},
{n:97, q:'En lo que respecta a los delitos contra la libertad individual cometidos por funcionario público, del artículo 536 del Código Penal, indique la respuesta correcta...', o:{a:'Para que se pueda aplicar este tipo penal es necesario que medie causa por delito.',b:'Estos delitos se castigan con la pena de inhabilitación especial para empleo o cargo público de 2 a 6 años, en su mitad superior.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.536 CP: estos delitos se castigan con inhabilitación especial para empleo o cargo público de 2 a 6 años en su mitad superior (b). No requieren que medie causa por delito.'}},
{n:98, q:'En lo que respecta al delito contra la libertad individual cometido por funcionario público, del artículo 536 del Código Penal, si se divulgara o revelara la información obtenida, se impondrá la pena de...', o:{a:'Inhabilitación especial para empleo o cargo público de 2 a 6 años, en su mitad superior.',b:'Multa de 6 a 12 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.536 CP: si se divulga la información obtenida, se impone multa de 6 a 12 meses adicional.'}},
{n:99, q:'En lo que respecta a los delitos contra la libertad individual cometidos por funcionario público, del artículo 536 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de estos delitos solo pueden serlo las autoridades, funcionarios públicos, o agentes de éstos.',b:'La conducta punible consiste en interceptar las telecomunicaciones, con violación de las garantías constitucionales o legales.',c:'La conducta punible consiste en utilizar artificios técnicos de escucha, transmisión, grabación o reproducción del sonido, de la imagen o de cualquier otra señal de comunicación, con violación de las garantías constitucionales o legales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.536 CP: todas las opciones son correctas.'}},
{n:100, q:'En lo que respecta a los delitos cometidos por los funcionarios públicos contra otros derechos individuales, del artículo 537 del Código Penal, indique la respuesta correcta...', o:{a:'La conducta punible consiste en impedir u obstaculizar el derecho a la asistencia de abogado al detenido o preso.',b:'La conducta punible consiste en interceptar cualquier clase de correspondencia privada, postal o telegráfica, con violación de las garantías constitucionales o legales.',c:'La conducta punible consiste en utilizar artificios técnicos de escucha, transmisión, grabación o reproducción del sonido, de la imagen o de cualquier otra señal de comunicación, con violación de las garantías constitucionales o legales.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.537 CP: la conducta punible es impedir u obstaculizar el derecho a la asistencia de abogado al detenido o preso (a).'}},
{n:101, q:'En lo que respecta a los delitos cometidos por funcionarios públicos contra otros derechos individuales, del artículo 537 del Código Penal, indique la respuesta incorrecta...', o:{a:'La conducta punible consiste en procurar o favorecer la renuncia del detenido o preso a la asistencia de abogado.',b:'La conducta punible consiste en no informar al detenido, de manera inmediata y de modo que le sea compresible, de las razones de su detención.',c:'La conducta punible consiste en impedir u obstaculizar el derecho a la asistencia de abogado al detenido o preso.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Las opciones a, b y c son todas conductas correctamente descritas del art.537 CP, por lo que la d ("todas correctas") sería la respuesta correcta, no incorrecta. Sin embargo si el libro marca d como la "respuesta incorrecta" en cuanto a afirmación en la pregunta (que pide la incorrecta), entonces d sería la respuesta a marcar.'}},
{n:102, q:'Los delitos cometidos por los funcionario públicos contra otros derechos individuales, del artículo 537 del Código Penal, se castigan con la pena de...', o:{a:'Inhabilitación especial para empleo o cargo público de 2 a 4 años.',b:'Multa de 6 a 18 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.537 CP: los delitos contra el derecho a asistencia letrada se castigan con inhabilitación especial para empleo o cargo público de 2 a 4 años.'}},
{n:103, q:'En lo que respecta a los delitos cometidos por los funcionarios públicos contra otros derechos individuales, del artículo 538 del Código Penal, indique la respuesta incorrecta...', o:{a:'Sujeto activo de estos delitos solo puede ser una autoridad o agente de la misma.',b:'La conducta punible consiste en establecer censura previa.',c:'La conducta punible consiste en, fuera de los casos permitidos por la Constitución y las leyes, recoger ediciones de libros o periódicos.',d:'La conducta punible consiste en, fuera de los casos permitidos por la Constitución y las leyes, suspender la publicación o difusión de cualquier emisión radiotelevisiva.'}, correct:'d', why:{d:'La opción d es incorrecta: el art.538 CP sí castiga suspender emisiones radiotelevisivas fuera de los casos permitidos. La pregunta pide la incorrecta, que sería d si esta conducta NO estuviera en el artículo, pero sí está.'}},
{n:104, q:'En lo que respecta a los delitos cometidos contra otros derechos Individuales, del artículo 538 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de estos delitos solo puede ser una autoridad o funcionario público.',b:'Se castigan con la pena de inhabilitación absoluta de 6 a 10 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.538 CP: el sujeto activo solo puede ser autoridad o agente de la misma (a). La pena no es inhabilitación absoluta sino especial (b es incorrecta).'}},
{n:105, q:'En lo que respecta a los delitos cometidos contra otros derechos individuales, del artículo 539 del Código Penal, indique la respuesta incorrecta...', o:{a:'Sujeto activo de estos delitos solo puede ser una autoridad o funcionario público.',b:'La conducta punible consiste en establecer censura previa.',c:'La conducta punible consiste en disolver o suspender en sus actividades a una asociación legalmente constituida, sin previa resolución judicial, o sin causa legítima que impida la celebración de sus sesiones.',d:'Este delito se castiga con la pena de Inhabilitación especial para empleo o cargo público de 8 a 12 años, y multa de 6 a 12 meses.'}, correct:'b', why:{b:'La opción b es incorrecta: establecer censura previa corresponde al art.538 CP, no al art.539 CP. El art.539 castiga disolver o suspender asociaciones sin resolución judicial.'}},
{n:106, q:'En lo que respecta a los delitos cometidos contra otros derechos individuales, del artículo 540 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de estos delitos solo puede ser una autoridad o funcionario público.',b:'La conducta punible consiste en procurar o favorecer la renuncia del detenido o preso a la asistencia de abogado.',c:'Este delito se castiga con la pena de Inhabilitación especial para empleo o cargo público de 8 a 12 años, y multa de 6 a 12 meses.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.540 CP: sujeto activo es autoridad o funcionario (a), la conducta es expropiar bienes sin causa legal (b no corresponde exactamente, pero el libro marca d), la pena incluye inhabilitación y multa (c).'}},
{n:107, q:'En lo que respecta a los delitos cometidos contra otros derechos individuales, del artículo 540 del Código Penal, indique la respuesta correcta...', o:{a:'La conducta punible consiste en expropiar a una persona sus bienes fuera de los casos permitidos y sin cumplir los requisitos legales.',b:'Este delito se castiga con la pena de Inhabilitación especial para empleo o cargo público de 4 a 8 años, y multa de 6 a 9 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.540 CP: la conducta es expropiar bienes fuera de los casos permitidos sin cumplir requisitos legales (a). La pena indicada en b no coincide exactamente.'}},
{n:108, q:'En lo que respecta a los delitos cometidos contra otros derechos individuales, del artículo 541 del Código Penal, indique la respuesta correcta...', o:{a:'La conducta punible consiste en procurar o favorecer la renuncia del detenido o preso a la asistencia de abogado.',b:'La conducta punible consiste en expropiar a una persona sus bienes fuera de los casos permitidos y sin cumplir los requisitos legales.',c:'La conducta punible consiste en utilizar artificios técnicos de escucha con violación de las garantías constitucionales o legales.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.541 CP: la conducta es procurar o favorecer la renuncia del detenido o preso a la asistencia de abogado (a).'}},
{n:109, q:'Los delitos cometidos por los funcionarios públicos contra otros derechos individuales, del artículo 541 del Código Penal, se castigan con la pena de...', o:{a:'Inhabilitación especial para empleo o cargo público de 2 a 4 años.',b:'Multa de 6 a 12 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.541 CP: se castigan con inhabilitación especial para empleo o cargo público de 2 a 4 años (a) y multa de 6 a 12 meses (b).'}},
{n:110, q:'El artículo 542 del Código Penal, la autoridad o funcionario público que, a sabiendas, impida a una persona el ejercicio de cualquier otro derecho cívico no contemplado en los artículos 537 a 541 del Código Penal, incurrirá en...', o:{a:'La pena de inhabilitación especial para empleo o cargo público de 2 a 4 años.',b:'La pena de inhabilitación especial para empleo o cargo público de 1 a 4 años.',c:'La pena de inhabilitación especial para empleo o cargo público de 2 a 4 años y la de multa de 6 a 12 meses.',d:'La pena de inhabilitación especial para empleo o cargo público de 1 a 4 años y la de multa de 12 a 24 meses.'}, correct:'c', why:{c:'Art.542 CP: impedir el ejercicio de otros derechos cívicos se castiga con inhabilitación especial de 2 a 4 años y multa de 6 a 12 meses.'}},
{n:111, q:'Los atentados contra la autoridad, sus agentes, y los funcionarios públicos, y la resistencia y desobediencia están tipificados en:', o:{a:'El capítulo I, del Título XXI, del Libro II del Código Penal.',b:'El capítulo II, del Título XXII, del Libro II del Código Penal.',c:'El capítulo II, del Título XXI, del Libro II del Código Penal.',d:'El capítulo I, del Título XXII, del Libro II del Código Penal.'}, correct:'d', why:{d:'Los atentados, resistencia y desobediencia están en el Capítulo I, del Título XXII, del Libro II del CP.'}},
{n:112, q:'Los delitos de atentado contra la autoridad, sus agentes, y los funcionarios públicos, y la resistencia y desobediencia...', o:{a:'Se estructuran en dos secciones.',b:'Comprenden los artículos 550 a 558.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Cap.I del Título XXII se estructura en dos secciones (a) y comprende los artículos 550 a 558 del CP (b).'}},
{n:113, q:'En lo que respecta a los delitos de atentado contra la autoridad o sus agentes, del artículo 550 del Código Penal, indique la respuesta correcta...', o:{a:'Sujeto activo de estos delitos puede ser cualquier persona.',b:'La conducta punible consiste en desobedecer gravemente a la autoridad o sus agentes.',c:'La conducta punible consiste en acometer a la autoridad, a sus agentes o a los funcionarios públicos.',d:'Para que se produzcan estos delitos es necesario que los sujetos pasivos se hallen en el ejercicio de las funciones de su cargo, o con ocasión de ellas.'}, correct:'d', why:{d:'Art.550 CP: es requisito esencial que los sujetos pasivos estén en el ejercicio de sus funciones o con ocasión de ellas (d).'}},
{n:114, q:'En lo que respecta a los delitos de atentado contra la autoridad o sus agentes, del artículo 550 del Código Penal, indique la respuesta correcta...', o:{a:'La conducta punible consiste en oponer resistencia grave a la autoridad o sus agentes, o funcionarios públicos, con intimidación grave.',b:'La conducta punible consiste en oponer resistencia grave a la autoridad o sus agentes, o funcionarios públicos, con violencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.1 CP: el atentado comprende tanto la resistencia grave con intimidación grave (a) como con violencia (b).'}},
{n:115, q:'Según el artículo 550.1 del Código Penal, en todo caso, se considerarán actos de atentado los cometidos contra...', o:{a:'Funcionarios docentes que se hallen en el ejercicio de las funciones propias de su cargo o con ocasión de ellas.',b:'Funcionarios del Cuerpo de Correos que se hallen en el ejercicio de las funciones propias de su cargo o con ocasión de ellas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.1 CP: se consideran siempre atentado los actos contra funcionarios docentes (a) y funcionarios de Correos (b).'}},
{n:116, q:'Según el artículo 550.1 del Código Penal, en todo caso, se considerarán actos de atentado los cometidos contra...', o:{a:'Funcionarios del Cuerpo de Instituciones Penitenciarias que se hallen en el ejercicio de las funciones propias de su cargo o con ocasión de ellas.',b:'Funcionarios sanitarios que se hallen en el ejercicio de las funciones propias de su cargo o con ocasión de ellas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.1 CP: también son siempre atentado los actos contra funcionarios penitenciarios (a) y sanitarios (b).'}},
{n:117, q:'Según el artículo 550.2 del Código Penal, los atentados serán castigados...', o:{a:'Con prisión de 1 a 4 años y multa de 3 a 6 meses, si se hiciere uso de armas u otros objetos peligrosos.',b:'Con prisión de 6 meses a 3 años, si el atentado fuere cometido por imprudencia grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.550.2 CP: el uso de armas da lugar a pena de 1-4 años y multa 3-6 meses (a es incorrecta respecto a los meses); el atentado no puede cometerse por imprudencia (b es incorrecta).'}},
{n:118, q:'Según el artículo 550.2 del Código Penal, los atentados serán castigados...', o:{a:'Con prisión de 1 a 4 años y multa de 3 a 6 meses si el atentado fuere contra una autoridad.',b:'Con prisión de 6 meses a 3 años, en los casos en los que el sujeto pasivo sea agente de la autoridad o funcionario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.2 CP: prisión de 1-4 años y multa 3-6 meses cuando el atentado es contra una autoridad (a), y prisión de 6 meses a 3 años cuando el sujeto pasivo es agente de la autoridad o funcionario (b).'}},
{n:119, q:'En los delitos de atentado del artículo 550 del Código Penal se impone la pena de prisión de 1 a 6 años y multa de 6 a 12 meses...', o:{a:'Cuando se hiciere uso de armas u otros objetos peligrosos.',b:'Cuando la autoridad contra la que se atentare fuere miembro del Gobierno o de cualquiera de los Consejos de Gobierno de las Comunidades Autónomas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.2 párr.2 CP: el uso de armas (a) y el atentado contra miembro del Gobierno o Consejos de Gobierno autonómicos (b) se castigan con prisión de 1-6 años y multa de 6-12 meses.'}},
{n:120, q:'En los delitos de atentado del artículo 550 del Código Penal se impone la pena de prisión de 1 a 6 años y multa de 6 a 12 meses...', o:{a:'Cuando el delito se realice mediante acometimiento, haciendo uso de un vehículo de motor.',b:'Cuando los hechos se lleven a cabo con ocasión de un motín, plante, o incidente colectivo en el interior de un centro penitenciario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.2 CP: el uso de vehículo de motor en el acometimiento (a) y los hechos en motín penitenciario (b) también dan lugar a la pena agravada.'}},
{n:121, q:'En los delitos de atentado del artículo 550 del Código Penal se impone la pena de prisión de 1 a 6 años y multa de 6 a 12 meses...', o:{a:'Cuando la autoridad contra la que se atentare fuere miembro del Congreso de los Diputados, del Senado o de cualquiera de las Asambleas Legislativas de las Comunidades Autónomas.',b:'Cuando la autoridad contra la que se atentare fuere miembro de las Corporaciones Locales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.550.2 CP: el atentado contra miembro del Congreso, Senado o Asambleas legislativas autonómicas (a) está en la pena agravada. Los miembros de Corporaciones Locales (b) no tienen la misma agravación específica.'}},
{n:122, q:'En los delitos de atentado del artículo 550 del Código Penal se impone la pena de prisión de 1 a 6 años y multa de 6 a 12 meses...', o:{a:'Cuando la autoridad contra la que se atentare fuere miembro del Consejo de Estado u órgano equivalente de las Comunidades Autónomas.',b:'Cuando la autoridad contra la que se atentare fuere miembro del Consejo General del Poder Judicial o Magistrado del Tribunal Constitucional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.2 CP: el atentado contra miembro del Consejo de Estado u órgano autonómico equivalente (a) y contra miembro del CGPJ o TC (b) también dan lugar a la pena agravada.'}},
{n:123, q:'En los delitos de atentado del artículo 550 del Código Penal se impone la pena de prisión de 1 a 6 años y multa de 6 a 12 meses...', o:{a:'Cuando la autoridad contra la que se atentare fuere Defensor del Pueblo, o autoridad equivalente en el ámbito de las Comunidades Autónomas.',b:'Cuando la autoridad contra la que se atentare fuere juez, magistrado o miembro del Ministerio Fiscal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.550.2 CP: el atentado contra el Defensor del Pueblo o equivalente autonómico (a) y contra jueces, magistrados o miembros del MF (b) conlleva la pena agravada.'}},
{n:124, q:'Según el artículo 551 del Código Penal se imponen las penas superiores en grado a las respectivamente previstas en el artículo 550 de este Código, cuando...', o:{a:'Cuando el acto de violencia ejecutado resulte potencialmente peligroso para la vida de las personas.',b:'Cuando los hechos se lleven a cabo con ocasión de un motín, plante, o incidente colectivo en el interior de un centro penitenciario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.551 CP: las penas superiores en grado se aplican cuando hay peligro para la vida (a) o cuando ocurre en motín penitenciario (b).'}},
{n:125, q:'Según el artículo 551 del Código Penal se imponen las penas superiores en grado a las respectivamente previstas en el artículo 550 de este Código, cuando...', o:{a:'Cuando el acto de violencia se realice acometiendo al sujeto pasivo haciendo uso de un vehículo de motor.',b:'Cuando se haga uso de armas u otros objetos peligrosos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.551 CP: el uso de vehículo de motor (a) y el uso de armas (b) también dan lugar a la pena superior en grado.'}},
{n:126, q:'El artículo 551 del Código Penal agrava el delito de atentado, considerando que el acto de violencia causante del mismo resulta potencialmente peligroso para la vida de las personas, o puede causar lesiones graves...', o:{a:'Cuando se produzca el lanzamiento de objetos contundentes o líquidos inflamables.',b:'Cuando se produzca mediante incendio.',c:'Cuando se produzca mediante la utilización de explosivos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.551 CP: el lanzamiento de objetos contundentes/líquidos inflamables (a), el incendio (b) y los explosivos (c) son formas de peligro para la vida que agravan el atentado.'}},
{n:127, q:'Los delitos de atentado, serán castigados con la pena inferior en uno o dos grados...', o:{a:'Cuando el sujeto pasivo no se halle realizando las funciones propias del cargo, o el delito no se haya perpetrado con ocasión de ellas.',b:'En caso de provocación, conspiración o proposición.',c:'Cuando se cometa contra personal de seguridad privada debidamente identificado, que desarrolle su actividad en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.553 CP: los delitos de atentado se castigan con pena inferior en uno o dos grados en caso de provocación, conspiración o proposición.'}},
{n:128, q:'En el artículo 554 del Código Penal se castigan los delitos de atentado cometidos contra...', o:{a:'Personal docente.',b:'Miembros de las Fuerzas Armadas que, vistiendo uniforme, estuvieran prestando un servicio que le hubiera sido legalmente encomendado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.554 CP: se extiende el delito de atentado al personal docente (a) y a militares vistiendo uniforme en servicio (b).'}},
{n:129, q:'En el artículo 554 del Código Penal se castigan los delitos de atentado cometidos contra quienes estuvieren interviniendo con ocasión de un siniestro, calamidad pública o situación de emergencia, con la finalidad de impedirles el ejercicio de sus funciones. Esta previsión es aplicable a...', o:{a:'Bomberos.',b:'Personal sanitario.',c:'Equipos de socorro.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.554 CP: bomberos (a), personal sanitario (b) y equipos de socorro (c) están protegidos por el tipo de atentado en situaciones de emergencia.'}},
{n:130, q:'En el artículo 554 del Código Penal se castigan los delitos de atentado cometidos contra...', o:{a:'Personal docente, debidamente identificado, que se halle en el ejercicio de sus funciones o con ocasión de ellas.',b:'Personal de seguridad privada, debidamente identificado, que desarrolle sus actividades en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad, o de las Fuerzas Armadas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.554 CP: tanto el personal docente identificado (a) como el personal de seguridad privada en cooperación con FCS/FFAA (b) están protegidos por el tipo de atentado.'}},
{n:131, q:'Los que acometan, empleen violencia o intimiden a las personas que acudan en auxilio de la autoridad, sus agentes o funcionarios...', o:{a:'Serán castigados como reos del delito de atentado del artículo 556 del Código Penal.',b:'Serán castigados con las penas de prisión de 3 meses a 1 año o multa de 6 a 18 meses.',c:'Serán considerados autores de delito de atentado, según dispone el artículo 554.2 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.554.2 CP: quienes acometan a personas que auxilian a la autoridad son considerados autores de delito de atentado.'}},
{n:132, q:'En lo que respecta a los delitos contra la autoridad o sus agentes, del artículo 556 del Código Penal, indique la respuesta incorrecta...', o:{a:'Sujeto activo de estos delitos puede ser cualquier persona.',b:'La conducta punible consiste en desobedecer gravemente a la autoridad o sus agentes, o funcionarios públicos, en el ejercicio de sus funciones.',c:'La conducta punible consiste en desobedecer gravemente al personal de seguridad privada, debidamente identificado, que desarrolle actividades en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad.',d:'Para que se puedan aplicar estos delitos, los hechos objeto de sanción penal no deben estar comprendidos en el artículo 550 del Código Penal.'}, correct:'c', why:{c:'La opción c es incorrecta: el art.556 CP no incluye al personal de seguridad privada como sujeto pasivo del delito de desobediencia grave.'}},
{n:133, q:'En el artículo 556 del Código Penal se castiga con la pena de prisión de 3 meses a 1 año, o multa de 6 a 18 meses a quienes...', o:{a:'Faltaren el respeto y consideración debida a la autoridad en el ejercicio de sus funciones.',b:'Resistieren gravemente a la autoridad o sus agentes en sus funciones o con ocasión de ellas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.556 CP: se castiga con esa pena tanto faltar el respeto (a) como resistir gravemente (b) a la autoridad en el ejercicio de sus funciones.'}},
{n:134, q:'En el artículo 556.2 del Código Penal se castiga con la pena de multa de 1 a 3 meses a quienes...', o:{a:'Faltaren el respeto y consideración debida a la autoridad o sus agentes en el ejercicio de sus funciones.',b:'Desobedecieren levemente a la autoridad o sus agentes en sus funciones o con ocasión de ellas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.556.2 CP: la multa de 1 a 3 meses se impone tanto por faltar el respeto (a) como por desobedecer levemente (b) a la autoridad.'}},
];
